<?php declare(strict_types='1'); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Password Hash Generator','description'=>'Generate SHA-256 hashes from passwords locally in your browser.','url'=>'https://smarttoolz.in/tools/password-hash-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Password Hash Generator</h1><p>Generate a SHA-256 hash locally.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="p" type="password" placeholder="Enter password"><button id="go" class="tool-btn">Generate Hash</button><textarea id="o" rows="5" readonly></textarea></div></section></main><script>go.onclick=async()=>{let b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(p.value));o.value=[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}</script><?php smarttoolz_tool_page_end(); ?>